package io.aetheris.orchestrator.api;
import io.aetheris.orchestrator.ingestion.*;import io.aetheris.orchestrator.memory.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/orchestrator/stage8/memory")
public class Stage8MemoryController {private final KnowledgeIngestionService ingestion;private final VectorMemoryIndexService vectors;public Stage8MemoryController(KnowledgeIngestionService ingestion,VectorMemoryIndexService vectors){this.ingestion=ingestion;this.vectors=vectors;}@PostMapping("/ingest") public KnowledgeIngestionResult ingest(@RequestBody IngestKnowledgeRequest r){return ingestion.ingest(r);}@PostMapping("/rebuild") public Map<String,Object> rebuild(){return Map.of("indexed",vectors.rebuild());}@GetMapping("/search") public List<VectorMemorySearchResult> search(@RequestParam String q,@RequestParam(required=false) MemoryScope scope,@RequestParam(required=false) String namespace,@RequestParam(defaultValue="false") boolean includeProtected,@RequestParam(defaultValue="10") int limit){return vectors.search(q,scope,namespace,includeProtected,limit);}}
